CREATE TABLE branches(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, UNIQUE(company_id,id));
INSERT INTO branches(id,company_id,name) SELECT id,id,'Main branch' FROM companies;
CREATE TABLE member_roles(user_id TEXT PRIMARY KEY REFERENCES users(id), company_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','administrator','dispatcher','supervisor','technician','finance','management')), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id));
INSERT INTO member_roles SELECT id,company_id,role FROM users;
CREATE TABLE branch_members(company_id TEXT NOT NULL, branch_id TEXT NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY(branch_id,user_id), FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id));
INSERT INTO branch_members SELECT company_id,company_id,id FROM users;
CREATE TABLE service_areas(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, branch_id TEXT NOT NULL, name TEXT NOT NULL, postcodes TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, UNIQUE(company_id,id), FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id));
ALTER TABLE jobs ADD COLUMN branch_id TEXT;
ALTER TABLE jobs ADD COLUMN service_area_id TEXT;
ALTER TABLE customers ADD COLUMN branch_id TEXT;
ALTER TABLE teams ADD COLUMN branch_id TEXT;
ALTER TABLE maintenance_contracts ADD COLUMN branch_id TEXT;
ALTER TABLE inventory_items ADD COLUMN branch_id TEXT;
ALTER TABLE followups ADD COLUMN branch_id TEXT;
ALTER TABLE notifications ADD COLUMN branch_id TEXT;
ALTER TABLE activities ADD COLUMN branch_id TEXT;
UPDATE jobs SET branch_id=company_id;
UPDATE customers SET branch_id=company_id;
UPDATE teams SET branch_id=company_id;
UPDATE maintenance_contracts SET branch_id=company_id;
UPDATE inventory_items SET branch_id=company_id;
UPDATE followups SET branch_id=company_id;
UPDATE notifications SET branch_id=company_id;
UPDATE activities SET branch_id=(SELECT branch_id FROM jobs WHERE id=activities.job_id) WHERE job_id IS NOT NULL;
UPDATE activities SET branch_id=(SELECT branch_id FROM customers WHERE id=activities.customer_id) WHERE branch_id IS NULL AND customer_id IS NOT NULL;
CREATE INDEX jobs_branch ON jobs(company_id,branch_id,status);
CREATE INDEX members_user ON branch_members(company_id,user_id,branch_id);
CREATE TABLE approval_policies(company_id TEXT NOT NULL REFERENCES companies(id), kind TEXT NOT NULL CHECK(kind IN ('quote_issue','job_completion')), enabled INTEGER NOT NULL DEFAULT 0, threshold_cents INTEGER NOT NULL DEFAULT 0, roles TEXT NOT NULL DEFAULT '["owner","administrator","supervisor","finance"]', two_person INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(company_id,kind));
CREATE TABLE approval_requests(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, job_id TEXT NOT NULL, quote_id TEXT, kind TEXT NOT NULL, target_hash TEXT NOT NULL, summary TEXT NOT NULL, requested_by TEXT NOT NULL REFERENCES users(id), decided_by TEXT REFERENCES users(id), state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected')), note TEXT NOT NULL DEFAULT '', consumed_at TEXT, created_at TEXT NOT NULL, decided_at TEXT, UNIQUE(company_id,id), FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id), FOREIGN KEY(company_id,quote_id) REFERENCES quotes(company_id,id));
CREATE TABLE company_branding(company_id TEXT PRIMARY KEY REFERENCES companies(id), trading_name TEXT NOT NULL DEFAULT '', accent TEXT NOT NULL DEFAULT '#07518a', footer TEXT NOT NULL DEFAULT '', logo BLOB, logo_mime TEXT, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE privacy_settings(company_id TEXT PRIMARY KEY REFERENCES companies(id), technician_contacts INTEGER NOT NULL DEFAULT 1, retention_days INTEGER NOT NULL DEFAULT 365, review_note TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE deletion_requests(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), requested_by TEXT NOT NULL REFERENCES users(id), state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','cancelled','erased')), reason TEXT NOT NULL, requested_at TEXT NOT NULL, eligible_at TEXT NOT NULL, cancelled_at TEXT, completed_at TEXT);
CREATE TABLE legal_holds(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), reason TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
ALTER TABLE companies ADD COLUMN deletion_state TEXT NOT NULL DEFAULT 'active';
CREATE TABLE billing_plans(id TEXT PRIMARY KEY, name TEXT NOT NULL, users_limit INTEGER NOT NULL, jobs_limit INTEGER NOT NULL, branches_limit INTEGER NOT NULL, features TEXT NOT NULL, price_cents INTEGER, paypal_price_cents INTEGER, paypal_plan_id TEXT, published INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
INSERT INTO billing_plans VALUES('development','Development evaluation',25,1000,10,'["automation","maintenance","stock","costs","reports","templates","branches","approvals","branding","export"]',NULL,NULL,NULL,0,1);
INSERT INTO billing_plans VALUES('solo','Solo',1,50,1,'["templates","export"]',NULL,NULL,NULL,0,1);
INSERT INTO billing_plans VALUES('team','Team',10,500,1,'["automation","maintenance","stock","costs","reports","templates","branding","export"]',NULL,NULL,NULL,0,1);
INSERT INTO billing_plans VALUES('business','Business',50,5000,10,'["automation","maintenance","stock","costs","reports","templates","branches","approvals","branding","export"]',NULL,NULL,NULL,0,1);
INSERT INTO billing_plans VALUES('enterprise','Enterprise',200,50000,100,'["automation","maintenance","stock","costs","reports","templates","branches","approvals","branding","export"]',NULL,NULL,NULL,0,1);
CREATE TABLE subscriptions(company_id TEXT PRIMARY KEY REFERENCES companies(id), plan_id TEXT NOT NULL REFERENCES billing_plans(id), state TEXT NOT NULL DEFAULT 'trialing' CHECK(state IN ('trialing','pending','active','past_due','cancelled','suspended','unpaid')), provider TEXT, provider_token TEXT, period_end TEXT NOT NULL, grace_end TEXT, cancel_at_period_end INTEGER NOT NULL DEFAULT 0, last_event_at TEXT, version INTEGER NOT NULL DEFAULT 1);
INSERT INTO subscriptions(company_id,plan_id,period_end) SELECT id,'development',strftime('%Y-%m-%dT%H:%M:%fZ','now','+14 days') FROM companies;
CREATE TABLE billing_checkouts(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), plan_id TEXT NOT NULL REFERENCES billing_plans(id), provider TEXT NOT NULL, currency TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), state TEXT NOT NULL DEFAULT 'pending', external_id TEXT, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE billing_events(id TEXT PRIMARY KEY, company_id TEXT REFERENCES companies(id), provider TEXT NOT NULL, external_id TEXT NOT NULL, type TEXT NOT NULL, payload TEXT NOT NULL, received_at TEXT NOT NULL, state TEXT NOT NULL, UNIQUE(provider,external_id));
CREATE TABLE billing_receipts(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), checkout_id TEXT NOT NULL REFERENCES billing_checkouts(id), provider TEXT NOT NULL, payment_id TEXT NOT NULL, currency TEXT NOT NULL, amount_cents INTEGER NOT NULL, recorded_at TEXT NOT NULL, UNIQUE(provider,payment_id));
